{
  "name": "UHFLI 锁相放大器",
  "name_en": "UHFLI Lock-in Amplifier",
  "manufacturer": "Zurich Instruments",
  "description": "Zurich Instruments UHFLI 是一款高精度锁相放大器/信号分析仪，可用于实验中的交流信号检测、解调与测量。根据驱动暴露的功能，它还支持与内置 AWG/序列器相关的程序编译、波形存储器读写以及命令表上传，适合量子测量与精密电子实验控制。",
  "description_en": "The Zurich Instruments UHFLI is a high-precision lock-in amplifier and signal analysis instrument used for AC signal detection, demodulation, and measurement in laboratory experiments. Based on the exposed driver functions, it also supports built-in AWG/sequencer operations such as program compilation, waveform memory read/write, and command table upload, making it suitable for quantum measurements and precision electronics experiments.",
  "actions": [
    {
      "action_name": "auto-check_status",
      "description": "检查设备或相关功能模块的当前状态。",
      "description_en": "Check the current status of the device or its related functional module."
    },
    {
      "action_name": "auto-load_validation_schema",
      "description": "加载命令表或相关配置的校验模式，用于验证上传内容是否合法。",
      "description_en": "Load the validation schema for a command table or related configuration to verify that uploaded content is valid."
    },
    {
      "action_name": "auto-upload_to_device",
      "description": "将命令表或相关配置上传到仪器设备。",
      "description_en": "Upload a command table or related configuration to the instrument."
    },
    {
      "action_name": "auto-load_from_device",
      "description": "从设备读取命令表或相关配置内容。",
      "description_en": "Load a command table or related configuration from the device."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用仪器的序列器/AWG 执行单元。",
      "description_en": "Enable the instrument's sequencer/AWG execution unit."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待当前序列器或相关任务执行完成。",
      "description_en": "Wait until the current sequencer or related task has completed."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译将要在设备序列器上运行的程序。",
      "description_en": "Compile a program intended to run on the device sequencer."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将序列器程序加载到设备中以供执行。",
      "description_en": "Load a sequencer program onto the device for execution."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "向设备的波形存储器写入波形数据。",
      "description_en": "Write waveform data to the device waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从设备的波形存储器读取波形数据。",
      "description_en": "Read waveform data from the device waveform memory."
    }
  ],
  "tag_hints": [
    "lock-in amplification",
    "signal demodulation",
    "Zurich Instruments",
    "AWG sequencing",
    "waveform memory",
    "command table",
    "quantum measurement"
  ]
}

